#pragma once

// Model downloads (plan docs/superpowers/plans/2026-10-23-model-downloads.md): the download cards'
// catalog, generated by tools/secure/download_catalog.py from upstream Strata's setup.py,
// Project Maya's maya.py and our own pins (tools/secure/catalog_pins.json; GGUF files only, owner
// rule O4) into secure_frontend/catalog/downloads.json and embedded at build time. Each entry is
// checked against hf_source's rules when read; an entry that breaks one is dropped (and counted),
// never half-used.

#include <cstddef>
#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace secure_frontend {

struct CatalogFile final {
  std::string path;                     // in the repository, a .gguf
  std::optional<std::uint64_t> size{};  // unset for Maya's entries (read from Hugging Face at start)
  std::string sha256;                   // 64 lowercase hex: the pin every download is checked against
  // an mmproj's own repository and revision (upstream's pins name another repository for some quants); empty: the entry's
  std::string repo{};
  std::string revision{};
};

struct DownloadEntry final {
  std::string id;          // [a-z0-9._-]{1,64}
  std::string name;        // display name
  std::string source;      // strata | maya | m-strata (our own pins, tools/secure/catalog_pins.json) | custom
  std::string family;
  // qwen | glm53 | deepseek | minimax | gemma4 | flint | raon1 (custom: the matched profile's, else qwen)
  std::string engine;
  std::string about;
  std::string repo;        // owner/name
  std::string revision;    // a 40-hex commit, or "main" (Maya; resolved and checked at start)
  std::vector<CatalogFile> files;
  std::string prepare;     // iq_pack | none | maya_pack (strata-prepare download --maya) | unsupported
  std::vector<std::string> pack_args;
  std::optional<std::string> expert_profile;
  std::optional<CatalogFile> mmproj;
  // Gemma 4's MTP draft file (owner 2026-10-28): always fetched with the model, and its card runs it (--mtp <file>).
  // Gemma 4 entries only, pinned to a commit with its size; its repository and revision the entry's unless it names its
  // own.
  std::optional<CatalogFile> mtp;
  // Owner 2026-10-29: the draft layer every Qwen3.8 model runs (an id of DownloadCatalog::draft_layers), built on this
  // machine from another checkpoint's tensors. Packed Qwen3.8 entries (iq_pack) only.
  std::optional<std::string> draft_layer;
};

// One tensor of a draft layer: the window [offset, offset + size) of a .safetensors shard of the layer's repository,
// and the SHA-256 of those bytes; it is fetched as tensors/<name>.bin.
struct CatalogTensor final {
  std::string name;
  std::string shard;
  std::uint64_t offset{0};
  std::uint64_t size{0};
  std::string sha256;
};

// A draft layer built from a checkpoint's tensors (owner 2026-10-29: Qwen3.8-Flash-Next's MTP layer, upstream's
// tools/mtp_fetch.py at its pinned revision; strata-prepare mtp builds it).
struct CatalogDraftLayer final {
  std::string id;
  std::string repo;       // owner/name
  std::string revision;   // a 40-hex commit
  std::vector<CatalogTensor> tensors;
};

struct DownloadCatalog final {
  std::vector<DownloadEntry> entries;
  std::size_t dropped{0};  // entries refused by a rule
  std::vector<CatalogDraftLayer> draft_layers;   // every one pinned whole (a layer with a tensor that is not is not read)
};

// The catalog's draft layer `id`, else nullptr.
[[nodiscard]] const CatalogDraftLayer* find_draft_layer(const DownloadCatalog& catalog, std::string_view id) noexcept;

// The catalog JSON (schema_version 1). A document that is not one gives an empty catalog.
[[nodiscard]] DownloadCatalog parse_download_catalog(std::string_view text);
// The embedded catalog/downloads.json (empty when the build had none).
[[nodiscard]] std::string_view embedded_download_catalog() noexcept;
// tools/secure/prepare_download.py as built (the prepare step, D7): written owner-only below
// <roots.state>/downloads at boot and run from there, never from the source tree.
[[nodiscard]] std::string_view embedded_prepare_script() noexcept;

}  // namespace secure_frontend
